        return new Source("<!DOCTYPE html>
<html>
    <head>
        <meta charset=\"UTF-8\">
        <title>{% block title %}M2L - Gestion Sportive{% endblock %}</title>
        <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 128 128%22><text y=%221.2em%22 font-size=%2296%22>⚫️</text><text y=%221.3em%22 x=%220.2em%22 font-size=%2276%22 fill=%22%23fff%22>sf</text></svg>\">
        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">

        {% block stylesheets %}
            <!-- Bootstrap 5 CSS -->
            <link href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css\" rel=\"stylesheet\" integrity=\"sha384-QWTKZyjpPEjISv5WaRU9OFeRpok6YctnYmDr5pNlyT2bRjXh0JMhjY6hW+ALEwIH\" crossorigin=\"anonymous\">
        {% endblock %}

        {% block javascripts %}
            <!-- Bootstrap 5 JS Bundle -->
            <script src=\"https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js\" integrity=\"sha384-YvpcrYf0tY3lHB60NNkmXc5s9fDVZLESaAA55NDzOxhy9GkcIdslK1eN7N6jIeHz\" crossorigin=\"anonymous\" defer></script>
            {% block importmap %}{{ importmap(\x27app\x27) }}{% endblock %}
        {% endblock %}

        {% set frankenphp_hot_reload = app.request.server.get(\x27FRANKENPHP_HOT_RELOAD\x27) %}
        {% if frankenphp_hot_reload %}
            <meta name=\"frankenphp-hot-reload:url\" content=\"{{ frankenphp_hot_reload }}\">
            <script src=\"https://cdn.jsdelivr.net/npm/idiomorph\"></script>
            <script src=\"https://cdn.jsdelivr.net/npm/frankenphp-hot-reload/+esm\" type=\"module\"></script>
        {% endif %}
    </head>
    <body class=\"bg-light\">
        <nav class=\"navbar navbar-expand-lg navbar-dark bg-primary mb-4\">
            <div class=\"container\">
                <a class=\"navbar-brand fw-bold\" href=\"{{ path(\x27app_main\x27) }}\">M2L Sport</a>
                <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#navbarNav\">
                    <span class=\"navbar-toggler-icon\"></span>
                </button>
                <div class=\"collapse navbar-collapse\" id=\"navbarNav\">
                    <ul class=\"navbar-nav me-auto\">
                        <li class=\"nav-item\">
                            <a class=\"nav-link\" href=\"{{ path(\x27app_objectif_index\x27) }}\">Objectifs</a>
                        </li>
                    </ul>
                    <ul class=\"navbar-nav\">
                        {% if app.user %}
                            <li class=\"nav-item\">
                                <span class=\"nav-link disabled text-white-50\">{{ app.user.email }}</span>
                            </li>
                            <li class=\"nav-item\">
                                <a class=\"btn btn-outline-light btn-sm ms-2 mt-1\" href=\"{{ path(\x27app_logout\x27) }}\">Déconnexion</a>
                            </li>
                        {% else %}
                            <li class=\"nav-item\">
                                <a class=\"btn btn-light btn-sm\" href=\"{{ path(\x27app_login\x27) }}\">Connexion</a>
                            </li>
                        {% endif %}
                    </ul>
                </div>
            </div>
        </nav>

        <main class=\"container\">
            {% block body %}{% endblock %}
        </main>
    </body>
</html>", "base.html.twig", "C:\\Users\\BLEURVACQ\\M2L\\templates\\base.html.twig");
